hooks.command:
node -e "
const chunks = [];
process.stdin.on('data', d => chunks.push(d));
process.stdin.on('end', () => {
  const input = JSON.parse(Buffer.concat(chunks).toString());
  const cmd = input.tool_input?.command || '';
  if (!/git\s+commit\b/.test(cmd)) process.exit(0);
  const { execSync, execFileSync } = require('child_process');
  const cwd = execSync('git rev-parse --show-toplevel', { encoding: 'utf8' }).trim();
  const steps = [
    ['Build', () => execSync('bun run build', { cwd, stdio: 'pipe' })],
    ['Lint', () => execSync('bun run lint', { cwd, stdio: 'pipe' })],
    ['Typecheck', () => execFileSync('bun', ['run', '--filter', '*', 'typecheck'], { cwd, stdio: 'pipe', shell: true })],
  ];
  const failures = [];
  for (const [label, run] of steps) {
    try { run(); }
    catch (e) {
      failures.push(label + ':\n' + (e.stdout?.toString() || e.message).slice(0, 400));
    }
  }
  if (failures.length > 0) {
    process.stdout.write(JSON.stringify({
      continue: false,
      stopReason: '\u274c Pre-commit checks failed:\n\n' + failures.join('\n\n') + '\n\nFix the issues above before committing.',
    }));
  }
});
"
